<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'new');if(in_array($status,['new','contacted','closed'],true))$pdo->prepare('UPDATE estimate_requests SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Estimate status updated.');header('Location: estimates.php');exit;}$rows=$pdo->query('SELECT * FROM estimate_requests ORDER BY id DESC')->fetchAll();$pageTitle='Estimate Requests';$active='estimates';require __DIR__.'/_header.php';?><p class="eyebrow">FREE ESTIMATES</p><h1>Customer requests</h1><div class="table-wrap"><table class="admin-table"><thead><tr><th>Customer</th><th>Contact</th><th>Project</th><th>Photo</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=h($r['full_name'])?></strong><br><small><?=h($r['address'])?></small></td><td><?=h($r['phone'])?><br><?=h($r['email'])?></td><td><strong><?=h($r['service_needed'])?></strong><br><?=nl2br(h($r['message']))?><br><small>Desired: <?=h($r['desired_date'])?> · <?=h($r['created_at'])?></small></td><td><?php if($r['photo_path']):?><a href="../<?=h($r['photo_path'])?>" target="_blank"><img class="thumb" src="../<?=h($r['photo_path'])?>" alt=""></a><?php endif;?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()"><option value="new" <?=$r['status']==='new'?'selected':''?>>New</option><option value="contacted" <?=$r['status']==='contacted'?'selected':''?>>Contacted</option><option value="closed" <?=$r['status']==='closed'?'selected':''?>>Closed</option></select></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/_footer.php';
